Review this React counter. Calling start more than once must not create extra timers, the count must increment every second using current state, and the timer must be cleaned up on unmount. Provide a corrected component.

function Counter() {
  const [count, setCount] = useState(0);
  function start() {
    setInterval(() => setCount(count + 1), 1000);
  }
  return <button onClick={start}>{count}</button>;
}

